arguments.command:
python3 -c "
import json
with open('/app/resources/treasury_bulletin_1992_03.json', 'r') as f:
    data = json.load(f)

# Search for TF-G
def find_key(d, target):
    if isinstance(d, dict):
        for k, v in d.items():
            if target in k:
                print(f'Found: {k}')
                print(v)
            find_key(v, target)
    elif isinstance(d, list):
        for item in d:
            find_key(item, target)

find_key(data, 'TF-G')
"
